//! The plate's water, traced in the plate's OWN pixel space
//! (generated by tools/plate_trace). The sphere is DERIVED, not
//! baked: every ring maps through `plate_chart()` — the bijective
//! pixel<->sphere chart fit over 12 detected city dots (mean residual
//! 1.6 km at ~75 m/px) — so map-space data and 3d stay one fact.
//! Lakes and the sea are traced areas; rivers are skeleton
//! centerlines rebuilt at the plate's true stroke width; the Jordan
//! is the corridor between the plate's two region fills, continuous
//! by construction. Every coordinate is a tracing marker, not a
//! place claim.

use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};

use atlas_graph_types::covenant::{ContentHash, SourceId};
use atlas_graph_types::covenant::{Ground, Justification};
use atlas_graph_types::covenant::{BibleLocus, LocusRange, VerseRef};
use atlas_graph_types::covenant::TimePoint;

use map_types::chart::Chart;
use map_types::{
    Boundary, BoundaryHistory, BoundaryId, BoundarySource, EdgeCharacter, Interval, Orientation,
    RegionClass, RegionGeom, RegionHistory, RegionId, RegionPart, UnitVec, WorldTimeline,
};

pub const PLATE_PROVENANCE: &str =
    "authored:plate-trace (georeferenced reference plate; affine over 12 city dots, mean 1.6 km)";

/// The plate's chart: pixel -> sphere, bijective on the plate frame.
pub fn plate_chart() -> Chart {
    Chart::new(
        [[7.423165730975e-04, -1.392245320025e-05], [-1.314773386506e-05, -6.519117998042e-04]],
        [3.354108963464e+01, 3.407261055596e+01],
        (0.0, 0.0, 4500.0, 6000.0),
    )
    .expect("the plate chart is non-degenerate")
}

