fn hash_id(tag: &str) -> ContentHash {
    let mut h = DefaultHasher::new();
    tag.hash(&mut h);
    ContentHash(h.finish())
}

/// The plate's water as a timeline of RegionClass::Water regions,
/// every point derived from plate pixels through `plate_chart()`.
pub fn plate_water_timeline(from: TimePoint) -> WorldTimeline {
    let gen_1_9_10 = || {
        let v = |verse| BibleLocus::whole(VerseRef { book: 1, chapter: 1, verse });
        LocusRange::new(v(9), v(10)).expect("GEN 1:9-10 is ordered")
    };
    let source = SourceId::new("authored:plate-trace");
    let justification = Justification {
        text: Some(
            "\"the gathering together of the waters called he Seas\" — shapes derived \
             from the reference plate through its chart (see provenance)."
                .to_string(),
        ),
        grounds: [Ground::Scripture(gen_1_9_10()), Ground::Source(source.clone())].into(),
    };
    let valid = Interval { from, to: None };
    let chart = plate_chart();
    let mut tl = WorldTimeline::default();

    let mut part = |tl: &mut WorldTimeline, tag: &str, ring: &[(f64, f64)]| -> RegionPart {
        let mut pts: Vec<UnitVec> = ring
            .iter()
            .map(|(x, y)| chart.to_sphere(*x, *y).expect("plate rings live on the plate"))
            .collect();
        pts.push(pts[0]);
        let bid = BoundaryId(hash_id(&format!("plate-water/{tag}")));
        tl.boundaries.insert(
            bid,
            BoundaryHistory {
                versions: vec![(
                    valid,
                    Boundary {
                        pts,
                        character: EdgeCharacter::Line,
                        source: BoundarySource::Imported { source: source.clone() },
                        justification: justification.clone(),
                        provenance: PLATE_PROVENANCE.to_string(),
                    },
                )],
            },
        );
        RegionPart { cycle: vec![(bid, Orientation::Forward)], holes: Vec::new() }
    };

    let mut region = |tl: &mut WorldTimeline, key: &str, label: &str, rings: &[&[(f64, f64)]]| {
        let parts: Vec<RegionPart> = rings
            .iter()
            .enumerate()
            .map(|(i, ring)| part(tl, &format!("{key}-{i}"), ring))
            .collect();
        tl.regions.insert(
            RegionId(hash_id(&format!("plate-water/{key}"))),
            RegionHistory {
                class: RegionClass::Water,
                label_history: vec![(valid, label.to_string())],
                geom_history: vec![(valid, RegionGeom { parts })],
            },
        );
    };

    region(&mut tl, "great-sea", "the Great Sea (plate)", &[PLATE_AREA_GREAT_SEA_0]);
    region(&mut tl, "jordan-waters", "the waters of the Jordan (plate)", &[PLATE_AREA_CHINNERETH_2, PLATE_AREA_CHINNERETH_3, PLATE_AREA_SALT_SEA_1, PLATE_JORDAN_0, PLATE_JORDAN_1, PLATE_JORDAN_2, PLATE_JORDAN_3]);
    region(&mut tl, "rivers", "the rivers of the land (plate)", &[PLATE_RIVER_0, PLATE_RIVER_1, PLATE_RIVER_2, PLATE_RIVER_3, PLATE_RIVER_4, PLATE_RIVER_5, PLATE_RIVER_6, PLATE_RIVER_7, PLATE_RIVER_8, PLATE_RIVER_9, PLATE_RIVER_10, PLATE_RIVER_11, PLATE_RIVER_12, PLATE_RIVER_13, PLATE_RIVER_14, PLATE_RIVER_15, PLATE_RIVER_16, PLATE_RIVER_17, PLATE_RIVER_18, PLATE_RIVER_19, PLATE_RIVER_20, PLATE_RIVER_21, PLATE_RIVER_22, PLATE_RIVER_23, PLATE_RIVER_24]);
    tl
}
